        check(getTargetContext().getPackageName().endsWith(".tests"),"isolated package");prior=Workspace.current(getTargetContext());Workspace.activate(getTargetContext(),UUID.randomUUID().toString());Context c=Workspace.context(getTargetContext());String roll;
