        main(()->{check(selected()==18,"all scans including unlinked selected");check(((String)field(state(),"date")).isEmpty(),"unknown date hidden");for(boolean dark:new boolean[]{false,true})for(float scale:new float[]{1f,1.6f}){Configuration cfg=new Configuration(original);cfg.uiMode=(cfg.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|(dark?Configuration.UI_MODE_NIGHT_YES:Configuration.UI_MODE_NIGHT_NO);cfg.fontScale=scale;activity.getResources().updateConfiguration(cfg,activity.getResources().getDisplayMetrics());call("show",new Class<?>[]{});for(int width:new int[]{320,375,414}){layout(width);bounds(root());ViewGroup header=root().findViewWithTag("library-header");check(header!=null&&header.getHeight()==LibraryUi.dp(activity,56),"shared navigation height");ImageView preview=(ImageView)field(activity,"preview");check(preview.getDrawable()!=null&&preview.getDrawable().getIntrinsicHeight()*4==preview.getDrawable().getIntrinsicWidth()*5,"4:5 preview content");check(preview.getHeight()<=activity.getResources().getDisplayMetrics().heightPixels*.42f,"preview fits editor controls");check(((Button)field(activity,"save")).isEnabled(),"save enabled after load");}}activity.getResources().updateConfiguration(original,activity.getResources().getDisplayMetrics());call("show",new Class<?>[]{});root().requestLayout();});snap("editor-light");
